function loadDashboard() {
    $.ajax({
        url: APP_URLS.count,
        type: "GET",
        success: function(t) {
            $("#organisasi_count").text(t.organisasi_count);
            $("#dataset_count").text(t.dataset_count);
            $("#infografis_count").text(t.infografis_count);
            $("#total_data").text(t.total_data);
        }
    });
}

function loadListData() {
    fetch(APP_URLS.list)
        .then(t => t.json())
        .then(t => {
            document.getElementById("dataset_container").innerHTML = t.dataset_html;
            document.getElementById("infografis_container").innerHTML = t.infografis_html;
        });
}



function loadTautan() {
    fetch(APP_URLS.tautan)
        .then(t => t.json())
        .then(t => {
            document.getElementById("tautan_container").innerHTML = t.html;
        })
        .catch(() => {
            document.getElementById("tautan_container").innerHTML = `
                <div class="text-center py-5 w-100">
                    <span class="text-danger">Gagal memuat tautan..</span>
                </div>
            `;
        });
}

function loadSlider() {
    fetch(APP_URLS.slider)
        .then(t => t.json())
        .then(t => {
            document.getElementById("slider_container").innerHTML = t.html;

            new bootstrap.Carousel(
                document.querySelector("#heroSlider"),
                {
                    interval: 4000,
                    ride: "carousel"
                }
            );
        });
}

$(document).ready(function () {

    loadDashboard();
    loadListData();
    loadTautan();
    loadSlider();


    const titleEl = document.getElementById("typingTitle");
    const descEl = document.getElementById("typingDesc");

    if (titleEl && descEl) {

        const slides = window.TEXT_SLIDES || [];

        let currentSlide = 0;

        function typeText(element, text, speed = 40) {
            return new Promise((resolve) => {

                element.innerHTML = "";
                let i = 0;

                const interval = setInterval(() => {

                    element.innerHTML += text.charAt(i);

                    i++;

                    if (i >= text.length) {
                        clearInterval(interval);
                        resolve();
                    }

                }, speed);

            });
        }

        async function startTyping() {

            while (true) {

                const item = slides[currentSlide];

                titleEl.innerHTML = "";
                descEl.innerHTML = "";

                await typeText(titleEl, item.title, 50);

                await typeText(descEl, item.desc, 20);

                await new Promise(r => setTimeout(r, 2500));

                currentSlide = (currentSlide + 1) % slides.length;
            }
        }

        if (slides.length > 0) {
            startTyping();
        }
    }

});